#pragma once
// ct/project/camera.h
// The project camera: zoom/pan keys (manual or generated by Auto-Zoom) and its continuous evaluation Camera::At.
// Thread model: plain values; At() is const and pure.

#include <ct/core/json.h>
#include <ct/core/types.h>
#include <ct/project/easing.h>

#include <vector>

namespace ct::project {

struct CameraKey {
    TimeUs t_us = 0;   // timeline time
    float zoom = 1, cx = 0.5f, cy = 0.5f;   // centre in normalized canvas coordinates
    Ease ease = Ease::InOut;                // easing towards the next key
    bool generated = false;                 // made by Auto-Zoom; Regenerate replaces only these
};

struct AutoZoomParams {
    float zoom = 2.0f;
    TimeUs min_hold_us = 1'200'000, lead_us = 150'000;
    int ease_ms = 650;
    bool follow = true;
    float follow_deadzone = 0.15f;
    bool on_click = true, on_typing = true;
    Json extra;
};

struct Camera {
    enum class Mode { Manual, Auto } mode = Mode::Auto;
    std::vector<CameraKey> keys;   // sorted by t_us, unique times
    AutoZoomParams auto_params;
    Json extra;

    struct View { float zoom, cx, cy; };
    // Surrounding keys; zoom interpolated in log2 space, centre linearly, both with the earlier key's easing (Hold
    // keeps the earlier key until the next one). Before the first / after the last key: that key. No keys: 1, .5, .5.
    // The centre is clamped so the visible window [c - 1/(2z), c + 1/(2z)] stays inside [0,1].
    View At(TimeUs t) const;

    // Inserts or replaces the key at key.t_us.
    void SetKey(const CameraKey& key);
    bool RemoveKey(TimeUs t);
    // Removes every generated key and merges `generated` in (a manual key wins over a generated one at the same time).
    void ReplaceGenerated(const std::vector<CameraKey>& generated);
    bool IsSorted() const;
};

// Clamps a centre coordinate for zoom z (z <= 1 -> 0.5).
float ClampCentre(float c, float zoom);

} // namespace ct::project
